class Solution {
public:
    vector<int> rowAndMaximumOnes(vector<vector<int>>& mat) {
        int maxOnes = -1;
        int ansIdx = 0;
        for (int i = 0; i < (int)mat.size(); ++i) {
            int cnt = 0;
            for (int v : mat[i]) {
                if (v == 1) ++cnt;
            }
            if (cnt > maxOnes) {
                maxOnes = cnt;
                ansIdx = i;
            }
        }
        return {ansIdx, maxOnes};
    }
};
